<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}
$error='';$batch=$_SESSION['issued_temp_batch']??[];$events=pg_query($conn,"SELECT id,title,start_at FROM events WHERE status IN ('draft','open','ongoing') ORDER BY start_at DESC");
if(($_GET['download']??'')==='csv'&&$batch){header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="temporary-student-accounts.csv"');$out=fopen('php://output','w');fputs($out,"\xEF\xBB\xBF");fputcsv($out,['Temporary ID','Temporary Password','Event Ticket']);foreach($batch as $row)fputcsv($out,[$row['code'],$row['password'],$row['ticket']]);fclose($out);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';elseif(!verify_admin_password($conn,$_SESSION['admin_id'],$_POST['admin_password']??''))$error='Correct administrator password is required.';else{$count=(int)($_POST['count']??0);$prefix=strtoupper(trim($_POST['prefix']??'TEMP'));$eventId=(int)($_POST['event_id']??0);if($count<1||$count>200)$error='Generate between 1 and 200 accounts per batch.';elseif(!preg_match('/^[A-Z0-9_-]{2,12}$/',$prefix))$error='Prefix must contain 2–12 letters, numbers, dashes, or underscores.';else{$batchCode='BATCH-'.strtoupper(bin2hex(random_bytes(3)));$created=[];pg_query($conn,'BEGIN');try{for($i=1;$i<=$count;$i++){$code=$prefix.'-'.strtoupper(bin2hex(random_bytes(3)));$password=substr(strtoupper(bin2hex(random_bytes(6))),0,10);$qr=bin2hex(random_bytes(24));$r=pg_query_params($conn,"INSERT INTO attendees(attendee_code,full_name,password_hash,must_complete_profile,qr_token,batch_code) VALUES($1,$2,$3,TRUE,$4,$5) RETURNING id",[$code,'Pending Student',password_hash($password,PASSWORD_DEFAULT),$qr,$batchCode]);if(!$r)throw new Exception('Account creation failed.');$attendeeId=(int)pg_fetch_result($r,0,0);$ticket='';if($eventId){$ticket=generate_public_code('TKT',5);$reg=pg_query_params($conn,"INSERT INTO event_registrations(event_id,attendee_id,ticket_code,status) SELECT $1,$2,$3,CASE WHEN e.capacity IS NOT NULL AND (SELECT COUNT(*) FROM event_registrations WHERE event_id=e.id AND status='registered')>=e.capacity THEN 'waitlisted' ELSE 'registered' END FROM events e WHERE e.id=$1",[$eventId,$attendeeId,$ticket]);if(!$reg)throw new Exception('Event registration failed.');}$created[]=['code'=>$code,'password'=>$password,'ticket'=>$ticket];}pg_query($conn,'COMMIT');$_SESSION['issued_temp_batch']=$created;$batch=$created;audit_log($conn,'temporary_accounts_generated','attendee_batch',$batchCode,['count'=>$count,'event_id'=>$eventId]);}catch(Throwable $e){pg_query($conn,'ROLLBACK');$error='The batch could not be generated.';}}
 }
}
admin_page_start('Bulk Temporary Accounts','attendees');?>
<div class="hero"><div><h2><i class="fas fa-users-gear"></i> Bulk Temporary Accounts</h2><p>Generate first-login accounts. Students complete their own information, choose permanent credentials, and receive a personal QR.</p></div><a class="btn secondary" href="index.php"><i class="fas fa-arrow-left"></i> Attendees</a></div><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?>
<div class="card"><h3>Generate account batch</h3><form method="post" class="form-grid"><?=csrf_field()?><div class="field"><label>Number of accounts</label><input type="number" name="count" min="1" max="200" value="20" required></div><div class="field"><label>Temporary ID prefix</label><input name="prefix" value="TEMP" maxlength="12" required></div><div class="field full"><label>Register immediately to event (optional)</label><select name="event_id"><option value="">No event yet</option><?php if($events):while($e=pg_fetch_assoc($events)):?><option value="<?=(int)$e['id']?>"><?=h($e['title'])?> · <?=h(date('M j, Y',strtotime($e['start_at'])))?></option><?php endwhile;endif;?></select></div><div class="field full"><label>Confirm administrator password</label><input type="password" name="admin_password" required autocomplete="current-password"></div><div class="field full"><button class="btn"><i class="fas fa-wand-magic-sparkles"></i> Generate Temporary Accounts</button></div></form></div>
<?php if($batch):?><div class="card"><div class="panel-header"><div><h3>Latest generated batch</h3><div class="help">Save this now. Temporary passwords are not stored in readable form.</div></div><a class="btn" href="?download=csv"><i class="fas fa-file-csv"></i> Download CSV</a></div><div class="table-wrap"><table><thead><tr><th>Temporary ID</th><th>Temporary Password</th><th>Event Ticket</th></tr></thead><tbody><?php foreach($batch as $row):?><tr><td><strong><?=h($row['code'])?></strong></td><td><strong><?=h($row['password'])?></strong></td><td><?=h($row['ticket']?:'Not assigned')?></td></tr><?php endforeach;?></tbody></table></div></div><?php endif;admin_page_end();?>
